	"cover" text,
	"facts" jsonb NOT NULL,
	"story_title" jsonb NOT NULL,
	"story" jsonb DEFAULT '{"zh":[],"en":[]}'::jsonb NOT NULL,
	"parts_kicker" jsonb NOT NULL,
	"parts_title" jsonb NOT NULL,
	"parts" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"lines_title" jsonb NOT NULL,
	"lines" jsonb DEFAULT '[]'::jsonb NOT NULL,
