-- The three films and the first idol as they stood in code (components/films,
-- components/idols and their copy in messages/*.json) on the day they moved here.
INSERT INTO "films" ("key", "title", "kicker", "subtitle", "latin", "meta", "lede", "year", "track", "accent", "ratio", "cover", "facts", "story_title", "story", "parts_kicker", "parts_title", "parts", "lines_title", "lines", "stills_kicker", "stills_title", "stills_lede", "stills", "credit", "draft", "sort") VALUES ('odyssey', '{"zh":"大话西游","en":"A Chinese Odyssey"}'::jsonb, '{"zh":"大话西游 · 1995","en":"A Chinese Odyssey · 1995"}'::jsonb, '{"zh":"一部看了很多遍的电影：上下两部，几张剧照，记得的几句台词，和片尾那首《一生所爱》。","en":"A film watched many times over: two parts, a few stills, the lines I remember, and the song over the end credits."}'::jsonb, '{"zh":"A Chinese Odyssey","en":"大话西游"}'::jsonb, '{"zh":"刘镇伟 · 周星驰 · 朱茵 · 莫文蔚 · 1995","en":"Jeffrey Lau · Stephen Chow · Athena Chu · Karen Mok · 1995"}'::jsonb, '{"zh":"《月光宝盒》和《大圣娶亲》1995 年上映时没多少人看懂，几年后在大学宿舍和录像厅里被一遍遍重看，成了很多人心里最好的那部周星驰。至尊宝、紫霞、白晶晶、月光宝盒——还有片尾那首《一生所爱》，进了这一页就会响起。","en":"Pandora''s Box and Cinderella baffled most people when they came out in 1995; a few years later they were watched over and over in university dorms and video halls, and became, for many, the best Stephen Chow there is. Joker, Zixia, Bai Jingjing, the Pandora''s Box — and the song over the end credits, 一生所愛, which plays while you are on this page."}'::jsonb, '1995', 'odyssey', '#b8552e', 'video', 'monkeyKing', '{"director":{"zh":"刘镇伟","en":"Jeffrey Lau"},"cast":{"zh":"周星驰 · 吴孟达 · 朱茵 · 莫文蔚 · 蓝洁瑛 · 罗家英","en":"Stephen Chow · Ng Man-tat · Athena Chu · Karen Mok · Yammie Lam · Law Kar-ying"},"released":{"zh":"1995.01.21 / 02.04 · 香港","en":"1995.01.21 / 02.04 · Hong Kong"},"runtime":{"zh":"88 + 95 分钟","en":"88 + 95 min"},"rating":{"zh":"9.0 / 9.2","en":"9.0 / 9.2"}}'::jsonb, '{"zh":"五百年前，五百年后","en":"Five hundred years before, five hundred years after"}'::jsonb, '{"zh":["五百年后，孙悟空转世成了斧头帮的至尊宝。为了救白晶晶，他靠着一只月光宝盒一次次回到同一个夜晚，结果宝盒把他送回了五百年前，在牛魔王的洞府里遇见了紫霞。要救紫霞，他得戴上金箍成为孙悟空；戴上金箍，就不能再有七情六欲。上下两部讲的就是这一个选择。"],"en":["Five hundred years on, the Monkey King has been reborn as Joker, chief of the Axe Gang. To save Bai Jingjing he uses the Pandora''s Box to land back in the same night again and again — until the box carries him five hundred years back instead, into the Bull King''s cave, where he meets Zixia. To save her he must put on the golden headband and become the Monkey King; with it on, he may feel nothing again. The two parts are that one choice."]}'::jsonb, '{"zh":"上下两部","en":"The two parts"}'::jsonb, '{"zh":"月光宝盒，与大圣娶亲","en":"Pandora''s Box, and Cinderella"}'::jsonb, '[{"title":{"zh":"大话西游之月光宝盒","en":"A Chinese Odyssey Part One: Pandora''s Box"},"meta":{"zh":"1995.01.21 · 上部","en":"1995.01.21 · Part one"},"note":{"zh":"五百年后，孙悟空转世成了斧头帮的至尊宝。白晶晶、春三十娘、一只月光宝盒——他想救一个人，却一次次回到同一个夜晚。","en":"Five hundred years on, the Monkey King has been reborn as Joker, chief of the Axe Gang. Bai Jingjing, Spider Woman, a box that turns back time — he wants to save one person, and keeps landing back in the same night."}},{"title":{"zh":"大话西游之大圣娶亲","en":"A Chinese Odyssey Part Two: Cinderella"},"meta":{"zh":"1995.02.04 · 下部","en":"1995.02.04 · Part two"},"note":{"zh":"月光宝盒把他带回五百年前，他遇见了紫霞仙子。要救她，就得戴上金箍；戴上金箍，就不能再爱她。","en":"The box carries him five hundred years back, where he meets the fairy Zixia. To save her he must put on the golden headband; with it on, he may never love her again."}}]'::jsonb, '{"zh":"记得的那几句","en":"The ones I remember"}'::jsonb, '[{"text":{"zh":"曾经有一份真诚的爱情放在我面前，我没有珍惜，等我失去的时候我才后悔莫及，人世间最痛苦的事莫过于此。如果上天能够给我一个再来一次的机会，我会对那个女孩子说三个字：我爱你。如果非要在这份爱上加上一个期限，我希望是……一万年。","en":"Once there was a sincere love in front of me, and I did not treasure it. Only when I lost it did I regret — there is no greater pain in this world. If heaven gave me one more chance, I would say three words to that girl: I love you. And if a limit had to be put on that love, I would want it to be… ten thousand years."},"meta":{"zh":"至尊宝 · 对紫霞","en":"Joker · to Zixia"}},{"text":{"zh":"我的意中人是个盖世英雄，有一天他会踩着七色云彩来娶我。我猜中了前头，可是我猜不着这结局。","en":"The one I love is a great hero. One day he will come for me on a cloud of seven colours. I guessed the beginning — but I could not guess the ending."},"meta":{"zh":"紫霞","en":"Zixia"}},{"text":{"zh":"你看那个人，好像一条狗啊。","en":"Look at that man. He looks like a dog."},"meta":{"zh":"紫霞 · 城楼上，片尾","en":"Zixia · on the city wall, at the end"}}]'::jsonb, '{"zh":"剧照 · 1995","en":"Stills · 1995"}'::jsonb, '{"zh":"留在眼里的几幕","en":"The scenes that stayed"}'::jsonb, '{"zh":"沙漠、城楼、盘丝洞、一场婚礼，和那一次眨眼。点开任何一张，进放映厅看大图。","en":"The desert, the city wall, the Spider Cave, a wedding, and that one wink. Open any of them for the screening room."}'::jsonb, '[{"id":"monkeyKing","src":"/films/odyssey/monkey-king.jpg","width":1800,"height":1013,"span":"wide","title":{"zh":"齐天大圣","en":"The Monkey King"},"meta":{"zh":"大圣娶亲 · 金色的天","en":"Cinderella · a golden sky"},"alt":{"zh":"戴上金箍的孙悟空扛着金箍棒，站在金色的天空下","en":"The Monkey King, headband on, with his staff across his shoulders under a golden sky"}},{"id":"wink","src":"/films/odyssey/wink.jpg","width":1280,"height":720,"span":"tall","focus":"24% 45%","title":{"zh":"那一次眨眼","en":"That wink"},"meta":{"zh":"大圣娶亲 · 紫霞","en":"Cinderella · Zixia"},"alt":{"zh":"紫霞仙子对着镜头眨了一下眼","en":"The fairy Zixia winking at the camera"}},{"id":"desert","src":"/films/odyssey/desert.jpg","width":1800,"height":1013,"span":"one","title":{"zh":"沙漠","en":"The desert"},"meta":{"zh":"大圣娶亲 · 沙丘上","en":"Cinderella · on the dunes"},"alt":{"zh":"无边的沙漠里，两个人并肩坐在沙丘顶上","en":"Two people sitting side by side on the crest of a dune in an endless desert"}},{"id":"reeds","src":"/films/odyssey/reeds.jpg","width":1800,"height":1013,"span":"one","title":{"zh":"草丛","en":"The reeds"},"meta":{"zh":"月光宝盒 · 至尊宝","en":"Pandora''s Box · Joker"},"alt":{"zh":"至尊宝站在一片粉红色的草丛里回头看","en":"Joker standing among pink reeds, looking back"}},{"id":"bride","src":"/films/odyssey/bride.jpg","width":1280,"height":720,"span":"one","title":{"zh":"凤冠","en":"The phoenix crown"},"meta":{"zh":"大圣娶亲 · 紫霞","en":"Cinderella · Zixia"},"alt":{"zh":"戴着凤冠、穿着红嫁衣的紫霞仙子","en":"The fairy Zixia in a phoenix crown and a red wedding dress"}},{"id":"wedding","src":"/films/odyssey/wedding.jpg","width":1800,"height":1011,"span":"one","title":{"zh":"婚礼","en":"The wedding"},"meta":{"zh":"大圣娶亲 · 牛魔王的洞府","en":"Cinderella · the Bull King''s cave"},"alt":{"zh":"一片红色的婚礼现场，紫霞、牛魔王和至尊宝站在一起","en":"A wedding all in red — Zixia, the Bull King and Joker standing together"}},{"id":"jingjing","src":"/films/odyssey/jingjing.jpg","width":1800,"height":1013,"span":"one","title":{"zh":"白晶晶","en":"Bai Jingjing"},"meta":{"zh":"月光宝盒 · 沙漠","en":"Pandora''s Box · the desert"},"alt":{"zh":"沙漠里，至尊宝抱着倒在地上的白晶晶","en":"In the desert, Joker holding Bai Jingjing where she has fallen"}},{"id":"cave","src":"/films/odyssey/cave.jpg","width":1800,"height":1012,"span":"one","title":{"zh":"盘丝洞","en":"The Spider Cave"},"meta":{"zh":"大圣娶亲 · 洞里","en":"Cinderella · inside"},"alt":{"zh":"至尊宝坐在盘丝洞里盘根错节的树根之间","en":"Joker sitting among the tangled roots inside the Spider Cave"}},{"id":"zixia","src":"/films/odyssey/zixia.jpg","width":1800,"height":1012,"span":"one","title":{"zh":"紫霞","en":"Zixia"},"meta":{"zh":"大圣娶亲 · 举起的手","en":"Cinderella · a raised hand"},"alt":{"zh":"紫霞仙子举起手，笑着看向镜头","en":"The fairy Zixia raising a hand, smiling at the camera"}},{"id":"box","src":"/films/odyssey/box.jpg","width":1800,"height":1013,"span":"one","title":{"zh":"月光宝盒","en":"Pandora''s Box"},"meta":{"zh":"月光宝盒 · 至尊宝","en":"Pandora''s Box · Joker"},"alt":{"zh":"至尊宝坐在地上，手里举着月光宝盒","en":"Joker sitting on the ground, holding up the Pandora''s Box"}},{"id":"gate","src":"/films/odyssey/gate.jpg","width":1280,"height":720,"span":"one","title":{"zh":"城门","en":"The gate"},"meta":{"zh":"大圣娶亲 · 孙悟空","en":"Cinderella · the Monkey King"},"alt":{"zh":"戴着金箍的孙悟空扛着棒，站在城门前","en":"The Monkey King, headband on, staff across his shoulders in front of a city gate"}},{"id":"wall","src":"/films/odyssey/wall.jpg","width":1800,"height":1013,"span":"full","focus":"60% 55%","title":{"zh":"城楼上","en":"On the city wall"},"meta":{"zh":"大圣娶亲 · 片尾","en":"Cinderella · the ending"},"alt":{"zh":"城楼上，两个人相拥站着，远处是雪山","en":"On the city wall, two people standing in an embrace, snow mountains in the distance"}}]'::jsonb, '{"zh":"剧照 © 1995 彩星电影公司 / 西安电影制片厂，取自 TMDB；片尾曲《一生所爱》（卢冠廷，1995）为本站自托管的录音，整首循环。仅作个人致敬之用。","en":"Stills © 1995 Choi Sing Film / Xi''an Film Studio, via TMDB; the closing song 一生所愛 (Lowell Lo, 1995) is a recording this site hosts itself, played whole and looped. A personal homage only."}'::jsonb, false, 0) ON CONFLICT ("key") DO NOTHING;
--> statement-breakpoint
INSERT INTO "films" ("key", "title", "kicker", "subtitle", "latin", "meta", "lede", "year", "track", "accent", "ratio", "cover", "facts", "story_title", "story", "parts_kicker", "parts_title", "parts", "lines_title", "lines", "stills_kicker", "stills_title", "stills_lede", "stills", "credit", "draft", "sort") VALUES ('secret', '{"zh":"不能说的秘密","en":"Secret"}'::jsonb, '{"zh":"不能说的秘密 · 2007","en":"Secret · 2007"}'::jsonb, '{"zh":"周杰伦的第一部导演作品：一间旧琴房、一首能把时间弹回去的曲子，和从琴房到教室的一百零八步。","en":"Jay Chou''s first film as director: an old piano room, a piece that plays time backwards, and the hundred and eight steps from the piano room to the classroom."}'::jsonb, '{"zh":"Secret","en":"不能說的·秘密"}'::jsonb, '{"zh":"周杰伦 · 桂纶镁 · 黄秋生 · 2007","en":"Jay Chou · Gwei Lun-mei · Anthony Wong · 2007"}'::jsonb, '{"zh":"2007 年夏天，周杰伦自导自演的第一部电影。淡江中学的红砖拱廊、一间快要拆掉的旧琴房、一首名字叫《Secret》的曲子——叶湘伦转学第一天在琴房里遇见的路小雨，总是欲言又止，只说那是秘密。片名那首歌，进了这一页就会响起。","en":"The summer of 2007, and the first film Jay Chou directed and starred in. The red-brick arcades of Tamkang, an old piano room about to be pulled down, a piece called Secret — and Lu Xiaoyu, whom Ye Xianglun meets in that room on his first day and who never quite answers a question. That, she says, is a secret. The title song plays while you are on this page."}'::jsonb, '2007', 'secret', '#8a6a3d', 'photo', 'piano', '{"director":{"zh":"周杰伦","en":"Jay Chou"},"cast":{"zh":"周杰伦 · 桂纶镁 · 黄秋生 · 曾恺玹","en":"Jay Chou · Gwei Lun-mei · Anthony Wong · Alice Tzeng"},"released":{"zh":"2007.07.27 · 台湾","en":"2007.07.27 · Taiwan"},"runtime":{"zh":"101 分钟","en":"101 min"},"rating":{"zh":"8.2","en":"8.2"}}'::jsonb, '{"zh":"从琴房到教室，一百零八步","en":"A hundred and eight steps"}'::jsonb, '{"zh":["叶湘伦转学到父亲任教的淡江艺术学校，第一天就在旧琴房里循着一段陌生的琴声，遇见了路小雨。他问她弹的是什么，她说，那是秘密。小雨时常不来上课，一场误会之后彻底消失；湘伦却在校史室一张 1979 年的合影里看见了她。琴房要拆的那天，他坐到琴前，把那首《Secret》从头弹起。"],"en":["Ye Xianglun transfers to the arts school where his father teaches, and on his first day follows an unfamiliar tune to the old piano room, where Lu Xiaoyu is playing. He asks what the piece is; that, she says, is a secret. She is often missing from class, and after one misunderstanding she vanishes for good — until he finds her in a class photograph from 1979 in the school''s archive. On the day the piano room is to be pulled down, he sits at the piano and plays Secret from the top."]}'::jsonb, '{"zh":"","en":""}'::jsonb, '{"zh":"","en":""}'::jsonb, '[]'::jsonb, '{"zh":"记得的那几句","en":"The ones I remember"}'::jsonb, '[{"text":{"zh":"我跟你说个秘密哦……我数过，从琴房到教室，一共一百零八步。","en":"I''ll tell you a secret… I counted. From the piano room to the classroom is a hundred and eight steps."},"meta":{"zh":"路小雨 · 对湘伦","en":"Lu Xiaoyu · to Xianglun"}},{"text":{"zh":"肖邦最爱的女人，他们在一起十年……最后还不是分开了。——但是，能够拥有十年，已经很长了。","en":"The woman Chopin loved most — they were together ten years… and still they parted. — But to have had ten years is already a long time."},"meta":{"zh":"湘伦与小雨 · 琴房里","en":"Xianglun and Xiaoyu · in the piano room"}},{"text":{"zh":"不管我们能不能见面，不管你会不会忘了我，我只想告诉你一个秘密：我爱你。","en":"Whether or not we meet again, whether or not you forget me, I only want to tell you one secret: I love you."},"meta":{"zh":"路小雨 · 写在《Secret》的琴谱上","en":"Lu Xiaoyu · written on the score of Secret"}}]'::jsonb, '{"zh":"剧照 · 2007","en":"Stills · 2007"}'::jsonb, '{"zh":"留在眼里的几幕","en":"The scenes that stayed"}'::jsonb, '{"zh":"琴房、拱廊、一场雨、一张 1979 年的合影，和天台上的落日。点开任何一张，进放映厅看大图。","en":"The piano room, the arcade, a rainy day, a photograph from 1979, and the sunset on the roof. Open any of them for the screening room."}'::jsonb, '[{"id":"piano","src":"/films/secret/piano.jpg","width":1628,"height":1080,"span":"wide","title":{"zh":"琴房","en":"The piano room"},"meta":{"zh":"第一次相遇 · 旧琴房","en":"First meeting · the old piano room"},"alt":{"zh":"旧琴房里，湘伦坐在钢琴前，小雨靠在琴的另一头","en":"In the old piano room, Xianglun at the piano and Xiaoyu leaning on its far end"}},{"id":"doorway","src":"/films/secret/doorway.jpg","width":1544,"height":1024,"span":"tall","focus":"58% 30%","title":{"zh":"门口","en":"The doorway"},"meta":{"zh":"小雨 · 琴房门外","en":"Xiaoyu · outside the piano room"},"alt":{"zh":"小雨站在琴房门口，低着头微笑","en":"Xiaoyu standing in the doorway of the piano room, head down, smiling"}},{"id":"corridor","src":"/films/secret/corridor.jpg","width":1500,"height":994,"span":"one","title":{"zh":"拱廊","en":"The arcade"},"meta":{"zh":"淡江中学 · 一百零八步","en":"Tamkang · a hundred and eight steps"},"alt":{"zh":"两人穿着黑外套并肩走在红砖拱廊里","en":"The two of them in black coats walking side by side down a red-brick arcade"}},{"id":"bike","src":"/films/secret/bike.jpg","width":1800,"height":1013,"span":"one","title":{"zh":"单车","en":"The bicycle"},"meta":{"zh":"放学路上","en":"The way home"},"alt":{"zh":"湘伦骑车，小雨坐在后座，一只手搭在他肩上","en":"Xianglun cycling with Xiaoyu on the back, one hand on his shoulder"}},{"id":"icecream","src":"/films/secret/icecream.jpg","width":1544,"height":1024,"span":"one","title":{"zh":"冰淇淋","en":"Ice cream"},"meta":{"zh":"淡水河边 · 黄昏","en":"The Tamsui riverside · dusk"},"alt":{"zh":"黄昏的河边，两个人举着冰淇淋碰了一下","en":"At dusk by the river, two people touching ice-cream cones together"}},{"id":"rain","src":"/films/secret/rain.jpg","width":1544,"height":1024,"span":"one","title":{"zh":"雨","en":"Rain"},"meta":{"zh":"两把伞","en":"Two umbrellas"},"alt":{"zh":"下雨的校园里，两人各撑一把伞并肩走着","en":"On a rainy campus, the two of them walking side by side under separate umbrellas"}},{"id":"duel","src":"/films/secret/duel.jpg","width":1544,"height":1024,"span":"one","title":{"zh":"斗琴","en":"The piano duel"},"meta":{"zh":"礼堂 · 对宇豪","en":"The hall · against Yuhao"},"alt":{"zh":"礼堂里，湘伦低头弹琴，身后坐满了看热闹的学生","en":"In the hall, Xianglun playing with his head down and the seats behind him full of students"}},{"id":"desk","src":"/films/secret/desk.jpg","width":1728,"height":735,"span":"one","title":{"zh":"课桌","en":"The desk"},"meta":{"zh":"1979 · 小雨","en":"1979 · Xiaoyu"},"alt":{"zh":"小雨伏在课桌上写字：我是小雨，我爱你，你爱我吗","en":"Xiaoyu bent over a desk, writing on it: I am Xiaoyu, I love you, do you love me"}},{"id":"photo1979","src":"/films/secret/photo1979.jpg","width":1500,"height":1000,"span":"one","title":{"zh":"合影","en":"The photograph"},"meta":{"zh":"1979 · 校史室","en":"1979 · the archive"},"alt":{"zh":"泛黄的照片里，小雨和年轻时的叶老师站在一起","en":"In a yellowed photograph, Xiaoyu standing beside the young Mr Ye"}},{"id":"guitar","src":"/films/secret/guitar.jpg","width":1280,"height":720,"span":"one","title":{"zh":"吉他","en":"The guitar"},"meta":{"zh":"叶老师 · 家里","en":"Mr Ye · at home"},"alt":{"zh":"叶老师坐在家里的窗前弹吉他","en":"Mr Ye playing the guitar by a window at home"}},{"id":"note","src":"/films/secret/note.jpg","width":1800,"height":758,"span":"one","title":{"zh":"琴谱上的话","en":"The words on the score"},"meta":{"zh":"Secret · 最后一页","en":"Secret · the last page"},"alt":{"zh":"泛黄的纸上手写着：不管我们能不能见面，不管你会不会忘了我，我只想告诉你一个秘密","en":"Handwriting on yellowed paper: whether or not we meet again, whether or not you forget me, I only want to tell you one secret"}},{"id":"rooftop","src":"/films/secret/rooftop.jpg","width":1544,"height":1024,"span":"full","focus":"50% 62%","title":{"zh":"天台","en":"The roof"},"meta":{"zh":"落日 · 淡水河","en":"Sunset · the Tamsui river"},"alt":{"zh":"天台的长椅上，两人并肩看着河上的落日","en":"On a bench on the roof, the two of them side by side, watching the sun set over the river"}}]'::jsonb, '{"zh":"剧照 © 2007 安乐影片 / 杰威尔音乐，官方剧照取自豆瓣电影与 TMDB；原声带里的《路小雨》（周杰伦，2007）为本站自托管的录音，整首循环。仅作个人致敬之用。","en":"Stills © 2007 Edko Films / JVR Music, official stills via Douban and TMDB; 路小雨, from the film''s own soundtrack (Jay Chou, 2007), is a recording this site hosts itself, played whole and looped. A personal homage only."}'::jsonb, false, 1) ON CONFLICT ("key") DO NOTHING;
--> statement-breakpoint
INSERT INTO "films" ("key", "title", "kicker", "subtitle", "latin", "meta", "lede", "year", "track", "accent", "ratio", "cover", "facts", "story_title", "story", "parts_kicker", "parts_title", "parts", "lines_title", "lines", "stills_kicker", "stills_title", "stills_lede", "stills", "credit", "draft", "sort") VALUES ('lala', '{"zh":"爱乐之城","en":"La La Land"}'::jsonb, '{"zh":"爱乐之城 · 2016","en":"La La Land · 2016"}'::jsonb, '{"zh":"一个想开俱乐部的钢琴师，一个想当演员的女孩：洛杉矶相爱，各自的梦想都成了真，只是没能是彼此的。","en":"A pianist who wants a club of his own, a barista who wants to act: in love in Los Angeles, both dreams come true — just not with each other."}'::jsonb, '{"zh":"La La Land","en":"爱乐之城"}'::jsonb, '{"zh":"瑞恩·高斯林 · 艾玛·斯通 · 2016","en":"Ryan Gosling · Emma Stone · 2016"}'::jsonb, '{"zh":"2016 年，达米恩·查泽雷把黄金年代的歌舞片放回了今天的洛杉矶：高架桥上的一场群舞，让弹爵士的塞巴斯汀和端咖啡的米娅跳进了同一座城。紫色的夜里相爱，梦想成真的路口分开。主题曲《Mia & Sebastian''s Theme》进了这一页就会响起。","en":"In 2016 Damien Chazelle set the golden-age musical down in today''s Los Angeles: a jam on the freeway throws Sebastian, who plays jazz, and Mia, who waits tables and fails auditions, into the same dance. They fall in love under a purple sky and let go where their dreams come true. Mia & Sebastian''s Theme plays while you are on this page."}'::jsonb, '2016', 'theme', '#3f5fd6', 'video', 'lamp', '{"director":{"zh":"达米恩·查泽雷","en":"Damien Chazelle"},"cast":{"zh":"瑞恩·高斯林 · 艾玛·斯通 · 约翰·传奇 · 罗丝玛丽·德威特","en":"Ryan Gosling · Emma Stone · John Legend · Rosemarie DeWitt"},"released":{"zh":"2016.12.09 · 美国","en":"2016.12.09 · U.S."},"runtime":{"zh":"128 分钟","en":"128 min"},"rating":{"zh":"8.4","en":"8.4"}}'::jsonb, '{"zh":"冬、春、夏、秋，又一个冬","en":"Winter, spring, summer, fall — and winter again"}'::jsonb, '{"zh":["冬天，米娅在片场的咖啡店端盘子、一场接一场地试镜，塞巴斯汀在酒吧弹自己想弹的爵士、被老板开除；一场高架上的堵车，把两个人撞进了同一支舞。春天，一部老电影和一晚星空让两人走近；夏天各自奔忙——米娅写自己的独角戏，塞巴斯汀加入了 Keith 的乐队，唱着自己不信的歌四处巡演；秋天，一顿晚餐把话说散了。独角戏演砸的那晚，米娅回了老家，一通电话又把她带回试镜间：一支清唱把她送去了巴黎，也在山间的小路上，把两人送到了分开。五年后的冬夜，已是演员的米娅走进一家叫 Seb''s 的爵士俱乐部，灯下的开场曲，把那条没走完的路从头到尾弹了一遍。"],"en":["In winter Mia waits tables on the studio lot and fails audition after audition, while Sebastian plays the jazz he believes in and is fired for it; a jam on the freeway throws the two of them into the same dance. In spring an old picture house and a planetarium full of stars draw them together; in summer each runs hard — Mia writing her one-woman show, Sebastian touring with Keith''s band, singing songs he doesn''t believe in — until autumn, and a dinner where it all comes apart. The night the show flops, Mia goes home; one phone call brings her back to a bare audition room, where one quiet song sends her to Paris — and, on a path above the city, the two of them apart. Five winters later, Mia the actress walks into a jazz club called Seb''s, and the opening number under the light plays the road they didn''t take, from the top."]}'::jsonb, '{"zh":"","en":""}'::jsonb, '{"zh":"","en":""}'::jsonb, '[]'::jsonb, '{"zh":"唱过、说过的几句","en":"The ones I remember"}'::jsonb, '[{"text":{"zh":"人们会来的。你对它有热情，而人们爱的，正是别人全力以赴的样子。你让他们想起了自己忘掉的东西。","en":"People will want to go to it because you''re passionate about it, and people love what other people are passionate about. You remind people of what they''ve forgotten."},"meta":{"zh":"米娅 · 对塞巴斯汀","en":"Mia, to Sebastian"}},{"text":{"zh":"敬那些做梦的人，哪怕他们显得有点傻。","en":"Here''s to the ones who dream, foolish as they may seem."},"meta":{"zh":"米娅 · 试镜时唱的《Audition (The Fools Who Dream)》","en":"Mia, at the audition — Audition (The Fools Who Dream)"}},{"text":{"zh":"我会一直爱你。——我也会一直爱你。","en":"I''m always gonna love you. — I''m always gonna love you, too."},"meta":{"zh":"米娅与塞巴斯汀 · 试镜后的路上","en":"Mia and Sebastian, on the path after the audition"}}]'::jsonb, '{"zh":"剧照 · 2016","en":"Stills · 2016"}'::jsonb, '{"zh":"留在眼里的几幕","en":"The scenes that stayed"}'::jsonb, '{"zh":"高架上的第一支舞、紫夜里的踢踏、栈桥的黄昏、放映厅的对望，和海报上那条琴键铺成的路。点开任何一张，进放映厅看大图。","en":"The dance on the freeway, the tap under a purple sky, dusk on the pier, a look across a cinema, and the posters'' road of piano keys. Open any of them for the screening room."}'::jsonb, '[{"id":"freeway","src":"/films/lala/freeway.jpg","width":1620,"height":1080,"span":"wide","title":{"zh":"高架","en":"The freeway"},"meta":{"zh":"开场 · Another Day of Sun","en":"Opening · Another Day of Sun"},"alt":{"zh":"堵成一片的高架桥上，人们从车流里跃起、张开双臂，穿绿上衣的女子跳得最高，远处是洛杉矶的天际线","en":"On a jammed freeway the drivers leap out of the traffic with their arms flung wide, a woman in a green top jumping highest, the skyline of Los Angeles far behind"}},{"id":"roommates","src":"/films/lala/roommates.jpg","width":1620,"height":1080,"span":"tall","focus":"50% 38%","title":{"zh":"室友","en":"Roommates"},"meta":{"zh":"出门前 · Someone in the Crowd","en":"Getting ready · Someone in the Crowd"},"alt":{"zh":"蓝墙的公寓走廊里，米娅抱着一条蓝裙子、双手捂住耳朵，穿红、绿、黄裙子的三位室友靠在墙边看着她","en":"In a blue apartment corridor Mia clutches a blue dress to herself with her hands over her ears, while her three roommates in red, green and yellow lean on the walls and watch her"}},{"id":"lovelyNight","src":"/films/lala/lovely-night.jpg","width":1800,"height":1012,"span":"one","title":{"zh":"良夜","en":"A lovely night"},"meta":{"zh":"山顶 · A Lovely Night","en":"The overlook · A Lovely Night"},"alt":{"zh":"俯瞰夜景的高台上，两人踢踏舞跳到同一拍，米娅的黄裙刚落，身后是紫色的星空，和一盏亮着的白色灯柱","en":"On an overlook above the city the two land the same tap step, Mia''s yellow dress just settled, a starry purple sky and one lit white lamppost behind"}},{"id":"piano","src":"/films/lala/piano.jpg","width":1800,"height":1012,"span":"one","title":{"zh":"灯塔窗","en":"The lighthouse window"},"meta":{"zh":"Lighthouse Café · 钢琴","en":"The Lighthouse Café · the piano"},"alt":{"zh":"砖墙的爵士俱乐部里，塞巴斯汀坐在钢琴前回头望，身后是一扇灯塔图案的圆形彩窗","en":"In a brick-walled jazz club Sebastian looks back from the piano bench, a round stained-glass window with a lighthouse behind him"}},{"id":"pier","src":"/films/lala/pier.jpg","width":1403,"height":789,"span":"one","title":{"zh":"栈桥","en":"The pier"},"meta":{"zh":"Hermosa Beach · 黄昏","en":"Hermosa Beach · dusk"},"alt":{"zh":"黄昏的栈桥上，塞巴斯汀独自走向画面深处，两侧立着老式灯柱，天空由粉转紫","en":"At dusk Sebastian walks alone down the pier, old lamp posts on either side, the sky turning from pink to violet"}},{"id":"stage","src":"/films/lala/stage.jpg","width":1624,"height":1080,"span":"one","title":{"zh":"银幕前","en":"Before the screen"},"meta":{"zh":"Rialto · 找人","en":"The Rialto · looking for him"},"alt":{"zh":"老影院的红色座椅之间，米娅穿绿裙背对镜头站在银幕前，放映机的光从正对面打来；右侧的过道上，穿浅褐西装的塞巴斯汀站着望向她","en":"Among the red seats of an old picture house Mia, in a green dress and seen from behind, stands before the screen with the projector''s beam shining straight at her; in the aisle to the right, Sebastian in a tan suit stands looking at her"}},{"id":"cinema","src":"/films/lala/cinema.jpg","width":1619,"height":1080,"span":"one","title":{"zh":"放映厅","en":"The cinema"},"meta":{"zh":"Rialto · 约会","en":"The Rialto · the date"},"alt":{"zh":"红色座椅的放映厅里，两人并肩而坐、侧过头对望，身后的观众虚成一片","en":"In the red seats of a picture house the two sit side by side and turn to each other, the audience a blur behind"}},{"id":"planetarium","src":"/films/lala/planetarium.jpg","width":1800,"height":1012,"span":"one","title":{"zh":"天文馆","en":"The planetarium"},"meta":{"zh":"格里菲斯天文馆 · 星空里","en":"Griffith Observatory · among the stars"},"alt":{"zh":"星空的投影里，两人手牵手腾空而起，脚下是化成一片蓝光的城市","en":"Inside a projection of stars the two rise into the air hand in hand, the city a blue blur below"}},{"id":"lamp","src":"/films/lala/lamp.jpg","width":1800,"height":1012,"span":"one","title":{"zh":"灯柱","en":"The lamppost"},"meta":{"zh":"海报 · 灯柱下的吻","en":"Poster · a kiss under the lamp"},"alt":{"zh":"夜色里两人靠着亮着的灯柱相拥亲吻，黄裙扬起，脚下是洛杉矶的灯海","en":"Against a lit lamppost at night the two embrace and kiss, the yellow dress caught mid-swing, Los Angeles glowing below"}},{"id":"messengers","src":"/films/lala/messengers.jpg","width":1620,"height":1080,"span":"one","title":{"zh":"巡演","en":"On tour"},"meta":{"zh":"The Messengers · 舞台","en":"The Messengers · on stage"},"alt":{"zh":"深红幕布前的舞台上，塞巴斯汀握着复古麦克风唱歌，身后是一片蓝色的光","en":"On a stage before a deep red curtain Sebastian sings into a vintage microphone, a wash of blue behind him"}},{"id":"moonDoor","src":"/films/lala/moon-door.jpg","width":1619,"height":1080,"span":"one","title":{"zh":"月门","en":"The moon door"},"meta":{"zh":"如果当初 · 幻境","en":"What if · the reverie"},"alt":{"zh":"圆形的门洞里，两人牵手背对镜头，望着一幅手绘的巴黎河岸：街钟、亮灯的楼窗和河水，地上落满红叶","en":"Through a round doorway the two stand hand in hand, backs to us, facing a hand-painted Paris riverbank — a street clock, lit windows, the water — with red leaves strewn on the ground"}},{"id":"keys","src":"/films/lala/keys.jpg","width":1800,"height":1012,"span":"full","title":{"zh":"琴键之路","en":"A road of piano keys"},"meta":{"zh":"海报 · 一条琴键铺的路","en":"Poster · a road paved in keys"},"alt":{"zh":"灰白的星空下，一排琴键弯成一条悬空的路，两人在路上相拥亲吻，米娅的黄裙扬起一条腿，路的另一头立着一盏亮着的灯柱，倒影落在下方的镜面上","en":"Under a grey, starry sky a row of piano keys curves into a road hung in the air; on it the two embrace and kiss, Mia''s yellow dress lifted with one leg, a lit lamppost at the far end, their reflection on the mirror-like floor below"}}]'::jsonb, '{"zh":"剧照 © 2016 Summit Entertainment / Lionsgate，宣传剧照取自 TMDB、官方剧照取自豆瓣电影；主题曲《Mia & Sebastian''s Theme》（Justin Hurwitz，2016）为本站自托管的录音，整首循环。仅作个人致敬之用。","en":"Stills © 2016 Summit Entertainment / Lionsgate, publicity stills via TMDB and official stills via Douban; Mia & Sebastian''s Theme (Justin Hurwitz, 2016) is a recording this site hosts itself, played whole and looped. A personal homage only."}'::jsonb, false, 2) ON CONFLICT ("key") DO NOTHING;
--> statement-breakpoint
INSERT INTO "idols" ("key", "name", "latin", "kicker", "years", "numbers", "lede", "accent", "cover", "gallery_kicker", "gallery_title", "gallery_lede", "photos", "timeline_kicker", "timeline_title", "timeline", "credit", "draft", "sort") VALUES ('kobe', '{"zh":"科比 · 布莱恩特","en":"Kobe Bryant"}'::jsonb, '{"zh":"Kobe Bryant","en":"Kobe Bean Bryant"}'::jsonb, '{"zh":"偶像 · 第一位","en":"Idols · the first"}'::jsonb, '1978 – 2020', '8 · 24', '{"zh":"洛杉矶湖人二十年，两个号码，五座总冠军，一场 81 分。凌晨四点的洛杉矶，是他留给后来人的一句话。","en":"Twenty years with the Lakers, two numbers, five championships, one night of 81. A Los Angeles at four in the morning is the line he left everyone after him."}'::jsonb, '#5b3f8a', 'hawaii8', '{"zh":"照片 · 2005 – 2024","en":"Photographs · 2005 – 2024"}'::jsonb, '{"zh":"球场上，和球场外","en":"On the court, and off it"}'::jsonb, '{"zh":"从 8 号到 24 号，从夏威夷的季前赛到瓦伦西亚的一面墙。","en":"From number 8 to number 24, from a preseason night in Hawaii to a wall in Valencia."}'::jsonb, '[{"id":"hawaii8","src":"/idols/kobe/kobe-bryant-8.jpg","width":1071,"height":1600,"author":"Sgt. Joseph A. Lee, U.S. Marine Corps","licence":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Kobe_Bryant_8.jpg","title":{"zh":"8 号","en":"Number 8"},"meta":{"zh":"夏威夷 · 季前赛 · 2005","en":"Hawaii · preseason · 2005"},"alt":{"zh":"身穿 8 号紫金球衣的科比站在罚球线上准备出手","en":"Kobe Bryant in the number 8 purple-and-gold jersey, set at the free-throw line"}},{"id":"hawaiiDunk","src":"/idols/kobe/kobe-bryant-dunk.jpg","width":1066,"height":1600,"author":"Cpl. Megan Stiner, U.S. Marine Corps","licence":"Public domain","page":"https://commons.wikimedia.org/wiki/File:Kobe_Bryant_dunk.jpg","title":{"zh":"挂在篮筐上","en":"Hanging on the rim"},"meta":{"zh":"夏威夷 · 季前赛 · 2005","en":"Hawaii · preseason · 2005"},"alt":{"zh":"科比扣篮后双手挂在篮筐上","en":"Kobe Bryant hanging from the rim with both hands after a dunk"}},{"id":"drives2007","src":"/idols/kobe/kobe-bryant-drives2.jpg","width":1130,"height":1600,"author":"Keith Allison","licence":"CC BY-SA 3.0","page":"https://commons.wikimedia.org/wiki/File:Kobe_Bryant_Drives2.jpg","title":{"zh":"突破","en":"The drive"},"meta":{"zh":"华盛顿 · 2007","en":"Washington · 2007"},"alt":{"zh":"科比运球突破奇才队的防守","en":"Kobe Bryant driving to the basket against the Wizards"}},{"id":"dunk2008","src":"/idols/kobe/bryant-about-to-dunk-2008.jpg","width":1121,"height":1600,"author":"Keith Allison","licence":"CC BY-SA 2.0","page":"https://commons.wikimedia.org/wiki/File:Bryant_about_to_dunk_2008.jpg","title":{"zh":"起跳","en":"Take-off"},"meta":{"zh":"华盛顿 · 2008","en":"Washington · 2008"},"alt":{"zh":"科比腾空即将扣篮","en":"Kobe Bryant in the air, about to dunk"}},{"id":"beijing2008","src":"/idols/kobe/kobe-bryant-beijing-olympics-men-s-semifinal-basketball.jpg","width":1066,"height":1600,"author":"Richard Giles","licence":"CC BY-SA 2.0","page":"https://commons.wikimedia.org/wiki/File:Kobe_Bryant_Beijing_Olympics_Men%27s_Semifinal_Basketball.jpg","title":{"zh":"北京","en":"Beijing"},"meta":{"zh":"奥运会半决赛 · 2008","en":"Olympic semifinal · 2008"},"alt":{"zh":"科比身穿美国队球衣在北京奥运会半决赛中","en":"Kobe Bryant in a Team USA jersey during the Beijing Olympics semifinal"}},{"id":"parade2009","src":"/idols/kobe/kobe-bryant-disney-parade.jpg","width":1248,"height":1600,"author":"LDCross","licence":"CC BY 2.0","page":"https://commons.wikimedia.org/wiki/File:Kobe_Bryant_Disney_Parade.jpg","title":{"zh":"冠军游行","en":"Victory parade"},"meta":{"zh":"迪士尼乐园 · 2009","en":"Disneyland · 2009"},"alt":{"zh":"科比在迪士尼乐园的湖人夺冠庆祝游行中向人群挥手","en":"Kobe Bryant waving to the crowd during the Lakers'' championship parade at Disneyland"}},{"id":"game2010","src":"/idols/kobe/kobe-bryant-in-2010-1.jpg","width":1600,"height":1200,"author":"Bryan Horowitz","licence":"CC BY-SA 2.0","page":"https://commons.wikimedia.org/wiki/File:Kobe_Bryant_in_2010-1.jpg","title":{"zh":"24 号","en":"Number 24"},"meta":{"zh":"2010","en":"2010"},"alt":{"zh":"身穿 24 号球衣的科比在比赛中","en":"Kobe Bryant in the number 24 jersey during a game"}},{"id":"obama2010","src":"/idols/kobe/2010-nba-champion-los-angeles-lakers-with-president-obama.jpg","width":1600,"height":1066,"author":"Lawrence Jackson, The White House","licence":"Public domain","page":"https://commons.wikimedia.org/wiki/File:2010_NBA_Champion_Los_Angeles_Lakers_with_President_Obama.jpg","title":{"zh":"白宫来客","en":"Visitors at the White House"},"meta":{"zh":"华盛顿 · 2010","en":"Washington · 2010"},"alt":{"zh":"2010 年总冠军湖人队与奥巴马总统在华盛顿的社区活动上","en":"The 2010 champion Lakers with President Obama at a community event in Washington"}},{"id":"london2012","src":"/idols/kobe/kobe-bryant-smiling-on-the-bench-usa-vs-gbr-2012.jpg","width":1600,"height":1066,"author":"Christopher Johnson","licence":"CC BY-SA 2.0","page":"https://commons.wikimedia.org/wiki/File:Kobe_Bryant_smiling_on_the_bench_USA_vs_GBR_2012.jpg","title":{"zh":"板凳上的笑","en":"A smile on the bench"},"meta":{"zh":"美国队 · 2012","en":"Team USA · 2012"},"alt":{"zh":"科比坐在美国队替补席上笑着","en":"Kobe Bryant smiling on the Team USA bench"}},{"id":"stage2013","src":"/idols/kobe/kobe-bryant-stage.jpg","width":1307,"height":1600,"author":"Neon Tommy","licence":"CC BY-SA 2.0","page":"https://commons.wikimedia.org/wiki/File:Kobe_Bryant_Stage.jpg","title":{"zh":"台上","en":"On stage"},"meta":{"zh":"2013","en":"2013"},"alt":{"zh":"科比在一场活动的舞台上","en":"Kobe Bryant on stage at an event"}},{"id":"farewell2015","src":"/idols/kobe/kobe-bryant-2015.jpg","width":1107,"height":1600,"author":"Keith Allison","licence":"CC BY-SA 2.0","page":"https://commons.wikimedia.org/wiki/File:Kobe_Bryant_2015.jpg","title":{"zh":"最后一季","en":"The last season"},"meta":{"zh":"华盛顿 · 2015","en":"Washington · 2015"},"alt":{"zh":"告别赛季的科比身穿 24 号球衣在场上","en":"Kobe Bryant in the number 24 jersey during his farewell season"}},{"id":"cabanyal2024","src":"/idols/kobe/kobe-bryant-cabanyal-02.jpg","width":1600,"height":1201,"author":"Francesc Fort","licence":"CC0","page":"https://commons.wikimedia.org/wiki/File:Kobe_Bryant_-_Cabanyal_02.jpg","title":{"zh":"墙上","en":"On the wall"},"meta":{"zh":"瓦伦西亚 · 2024","en":"Valencia · 2024"},"alt":{"zh":"瓦伦西亚 Cabanyal 街区一面画着科比的涂鸦墙","en":"A mural of Kobe Bryant on a wall in the Cabanyal district of Valencia"}}]'::jsonb, '{"zh":"生涯 · 节点","en":"Career · milestones"}'::jsonb, '{"zh":"从费城到洛杉矶","en":"Philadelphia to Los Angeles"}'::jsonb, '[{"date":"1978.08.23","title":{"zh":"生于费城","en":"Born in Philadelphia"},"note":{"zh":"父亲乔·布莱恩特也是 NBA 球员；童年有七年在意大利度过。","en":"His father Joe Bryant played in the NBA too; seven years of his childhood were spent in Italy."}},{"date":"1996.06","title":{"zh":"高中直接进入 NBA","en":"Straight from high school"},"note":{"zh":"首轮第 13 顺位被黄蜂选中，随即交易到湖人，17 岁。","en":"Picked 13th by the Hornets and traded to the Lakers at once — at 17."}},{"date":"2000 – 2002","title":{"zh":"三连冠","en":"Three-peat"},"note":{"zh":"与奥尼尔一起，湖人三年三座总冠军。","en":"Three titles in three years, beside Shaquille O''Neal."}},{"date":"2006.01.22","title":{"zh":"81 分","en":"81 points"},"note":{"zh":"对多伦多猛龙，NBA 历史单场第二高分。","en":"Against the Toronto Raptors — the second-highest single game in NBA history."}},{"date":"2008","title":{"zh":"常规赛 MVP · 北京金牌","en":"MVP · gold in Beijing"},"note":{"zh":"生涯唯一一座 MVP；同年夏天随「救赎之队」在北京夺金。","en":"His one regular-season MVP; that summer, gold with the Redeem Team."}},{"date":"2009 – 2010","title":{"zh":"两连冠","en":"Back to back"},"note":{"zh":"两届总决赛 MVP；第五座总冠军。","en":"Finals MVP both times; the fifth championship."}},{"date":"2016.04.13","title":{"zh":"告别战 60 分","en":"60 in the last game"},"note":{"zh":"对爵士，生涯最后一场，60 分。","en":"Against the Jazz, the final game of his career: 60 points."}},{"date":"2017.12.18","title":{"zh":"两件球衣同时退役","en":"Two jerseys retired"},"note":{"zh":"8 号与 24 号一起升上斯台普斯中心的穹顶。","en":"8 and 24 went up into the rafters of Staples Center together."}},{"date":"2018.03.04","title":{"zh":"奥斯卡","en":"An Oscar"},"note":{"zh":"《亲爱的篮球》获最佳动画短片。","en":"Dear Basketball won Best Animated Short Film."}},{"date":"2020.01.26","title":{"zh":"离开","en":"Gone"},"note":{"zh":"与女儿 Gianna 在卡拉巴萨斯的直升机事故中离世，41 岁。同年入选奈史密斯篮球名人堂。","en":"Killed with his daughter Gianna in a helicopter crash in Calabasas, at 41. Elected to the Naismith Hall of Fame the same year."}},{"date":"2024.02.08","title":{"zh":"铜像","en":"The statue"},"note":{"zh":"8 号球衣、指天的手，立在 Crypto.com 球馆外的 Star Plaza。","en":"Number 8, a finger to the sky, on Star Plaza outside Crypto.com Arena."}}]'::jsonb, '{"zh":"照片来自 Wikimedia Commons，各按其授权使用（作者与许可见每张图下）；铜像为程序化几何，仅作个人致敬之用。","en":"Photographs from Wikimedia Commons, each under its own licence (author and licence under every picture); the statue is procedural geometry, a personal homage only."}'::jsonb, false, 0) ON CONFLICT ("key") DO NOTHING;
